import csv
import json
import urllib.request
from datetime import date, timedelta
from pathlib import Path

stations = [s.strip() for s in Path('/root/data/michigan_stations.txt').read_text().splitlines() if s.strip()]

start = date(2025, 4, 1)
end = date(2025, 4, 7)
num_days = (end - start).days + 1
valid_dates = { (start + timedelta(days=i)).isoformat() for i in range(num_days) }


def fetch_json(url):
    with urllib.request.urlopen(url, timeout=30) as resp:
        return json.loads(resp.read().decode('utf-8'))


def get_minor_flood_stage(site):
    url = f'https://api.water.noaa.gov/nwps/v1/gauges/{site}'
    try:
        data = fetch_json(url)
    except Exception:
        return None
    flood = data.get('flood') or {}
    cats = flood.get('categories') or {}
    minor = cats.get('minor') or {}
    stage = minor.get('stage')
    if stage in (None, -9999):
        return None
    try:
        return float(stage)
    except Exception:
        return None


def count_flood_days(site, threshold_stage):
    # Use gage height (00065) instantaneous values; flag a day if any obs >= threshold
    url = (
        'https://waterservices.usgs.gov/nwis/iv/?format=json'
        f'&sites={site}&parameterCd=00065'
        f'&startDT={start.isoformat()}&endDT={(end + timedelta(days=1)).isoformat()}'
    )
    try:
        data = fetch_json(url)
    except Exception:
        return 0

    series = data.get('value', {}).get('timeSeries', [])
    if not series:
        return 0

    flood_dates = set()
    for ts in series:
        # Ensure we're reading gage height data
        var = ts.get('variable', {})
        codes = var.get('variableCode') or []
        if codes:
            code = codes[0].get('value')
            if code != '00065':
                continue
        values_list = ts.get('values') or []
        if not values_list:
            continue
        for entry in values_list[0].get('value', []):
            val = entry.get('value')
            if val in (None, ''):
                continue
            try:
                stage = float(val)
            except Exception:
                continue
            if stage < threshold_stage:
                continue
            dt = entry.get('dateTime', '')
            day = dt.split('T')[0]
            if day in valid_dates:
                flood_dates.add(day)
    return len(flood_dates)


results = []
for site in stations:
    threshold = get_minor_flood_stage(site)
    if threshold is None:
        continue
    flood_days = count_flood_days(site, threshold)
    if flood_days >= 1:
        results.append((site, flood_days))

results.sort(key=lambda x: x[0])

out_path = Path('/root/output/flood_results.csv')
out_path.parent.mkdir(parents=True, exist_ok=True)
with out_path.open('w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    writer.writerows(results)

print(f'Wrote {len(results)} stations to {out_path}')
