{"cmd":"python3 - <<'PY'
import csv
import json
import urllib.request
from urllib.parse import quote
from datetime import date, timedelta
from pathlib import Path

stations = [s.strip() for s in Path('/root/data/michigan_stations.txt').read_text().splitlines() if s.strip()]

start = date(2025, 4, 1)
end = date(2025, 4, 7)
valid_dates = { (start + timedelta(days=i)).isoformat() for i in range((end - start).days + 1) }


def fetch_json(url, timeout=60):
    with urllib.request.urlopen(url, timeout=timeout) as resp:
        return json.loads(resp.read().decode('utf-8'))


def get_minor_flood_stage(site):
    url = f'https://api.water.noaa.gov/nwps/v1/gauges/{site}'
    try:
        data = fetch_json(url, timeout=20)
    except Exception:
        return None
    flood = data.get('flood') or {}
    cats = flood.get('categories') or {}
    minor = cats.get('minor') or {}
    stage = minor.get('stage')
    if stage in (None, -9999):
        return None
    try:
        return float(stage)
    except Exception:
        return None


# Fetch thresholds per station
thresholds = {}
for site in stations:
    stage = get_minor_flood_stage(site)
    if stage is not None:
        thresholds[site] = stage

# Fetch all gage-height IV data in one call
sites_param = ','.join(stations)
url = (
    'https://waterservices.usgs.gov/nwis/iv/?format=json'
    f'&sites={quote(sites_param)}&parameterCd=00065'
    f'&startDT={start.isoformat()}&endDT={(end + timedelta(days=1)).isoformat()}'
)

data = fetch_json(url, timeout=120)
series_list = data.get('value', {}).get('timeSeries', [])

# Prepare per-station flood day tracking
flood_days = {site: set() for site in stations}

for ts in series_list:
    source = ts.get('sourceInfo', {})
    site_codes = source.get('siteCode') or []
    if not site_codes:
        continue
    site = site_codes[0].get('value')
    if site not in thresholds:
        continue
    threshold = thresholds[site]

    values_list = ts.get('values') or []
    if not values_list:
        continue
    for entry in values_list[0].get('value', []):
        val = entry.get('value')
        if val in (None, ''):
            continue
        try:
            stage = float(val)
        except Exception:
            continue
        if stage < threshold:
            continue
        dt = entry.get('dateTime', '')
        day = dt.split('T')[0]
        if day in valid_dates:
            flood_days[site].add(day)

results = [(site, len(days)) for site, days in flood_days.items() if len(days) >= 1]
results.sort(key=lambda x: x[0])

out_path = Path('/root/output/flood_results.csv')
out_path.parent.mkdir(parents=True, exist_ok=True)
with out_path.open('w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    writer.writerows(results)

print(f'Wrote {len(results)} stations to {out_path}')
PY"}
